DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.id=rm.menu_id
WHERE m.id IN (9100000000180,9100000000800,9100000000801,9100000000802,9100000000803,
  9100000000804,9100000000805,9100000000806,9100000000807,9100000000850,9100000000851,
  9100000000852,9100000000853,9100000000854,9100000000855)
  AND m.creator='CloudMold';
DELETE FROM system_menu WHERE id IN (9100000000850,9100000000851,9100000000852,9100000000853,
  9100000000854,9100000000855,9100000000800,9100000000801,9100000000802,9100000000803,9100000000804,
  9100000000805,9100000000806,9100000000807,9100000000180)
  AND creator='CloudMold';
DELETE r FROM system_role r
WHERE r.code='customer_sales_operator'
  AND r.creator='CloudMold:crm-navigation'
  AND NOT EXISTS (SELECT 1 FROM system_user_role ur WHERE ur.role_id=r.id);
